# Test generator of this problem (the judge runs it to rebuild the big tests).
import base64, os, random, zlib

random.seed(4602)
MAXN, MAXQ, MAXP, MAXT = 100000, 100000, 10**9, 10**15
tests = []


def add(k, p, t):
    n, q = len(p), len(t)
    assert 1 <= n <= MAXN and 1 <= q <= MAXQ and 1 <= k <= 10**9
    assert all(1 <= x <= MAXP for x in p) and all(1 <= x <= MAXT for x in t)
    tests.append(f"{n} {k} {q}\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, t)) + "\n")


def targets(n, hi, q, mode):
    out = []
    for _ in range(q):
        r = random.random()
        if mode == "high" and r < 0.9:
            t = random.randint(max(1, hi - hi // 20), hi)
        elif r < 0.08:
            t = random.randint(hi + 1, min(MAXT, hi + 10**12))
        elif r < 0.3:
            random.randint(1, n), random.random()
            t = next(FIXED)
        else:
            t = random.randint(1, hi)
        out.append(t)
    return out


def rnd(n, lo, hi):
    return [random.randint(lo, hi) for _ in range(n)]


def build():

    add(2, [4, 9, 1, 7, 3], [10, 27, 100])
    add(5, [5, 5, 5], [15, 16])
    add(1, [1000] * 4, [1000, MAXT])
    add(3, [1, 2, 3, 4, 5, 6], [6, 7, 15, 22, 25, 27])
    add(1, [7], [7, 15])

    add(1, [3, 1], [1, 2, 3, 4, 5, 6, 7, 8])
    for n, k, hi in [(6, 1, 5095756462), (8, 2, 6177), (10, 3, 8614), (12, 1, 10703), (12, 5, 96), (13, 12, 98),
                     (14, 2, 10340263459)]:
        p = rnd(n, 1, random.choice([10, 1000, MAXP]))
        add(k, p, targets(n, hi, 40, "any"))

    add(7, rnd(3000, 1, MAXP), targets(3000, 1873244992334, 3000, "any"))
    add(1, rnd(5000, 1, 100), targets(5000, 444221, 5000, "any"))

    N, Q = MAXN, MAXQ
    for k, lo, hi in [(1, 1, 87401341230898), (2, MAXP - 1000, 133332944569690), (3, 1, 71787322704182),
                      (10, 1, 58459244287172), (999, 1, 50131238280141), (N, 1, 50021800770316),
                      (10**9, MAXP, 100000000000000)]:
        p = [MAXP] * N if lo == MAXP else rnd(N, lo, MAXP)
        add(k, p, targets(N, hi, Q, "high"))
    add(4, rnd(N, 1, MAXP), targets(N, 68147670423178, Q, "any"))
    add(2, sorted(rnd(N, 1, MAXP)), targets(N, 77863406843060, Q, "high"))
    assert next(FIXED, None) is None


